  anchor: 'go', cta: 'GO → RITUAL → RETURN', devLabel: 'THE ENTIRE ENTRY', devCap: 'One sentence. Preserved at its own scale.',
  device: '      <div class="dj49-go" aria-hidden="true"><p lang="zh-Hant">十五日詣上清宮，亦有對御，至晚回內。</p></div>',
